-- Function call forms (any name, special argument syntax)
SELECT ABS(-1), SQRT(4), POWER(2, 10), ROUND(1.2345, 2), TRUNC(1.9), MOD(10, 3), RAND(), RANDOM_UUID();
SELECT LENGTH(name), UPPER(name), LOWER(name), TRIM(name), LTRIM(name), RTRIM(name), REPLACE(name, 'a', 'b') FROM t;
SELECT LEFT(name, 3), RIGHT(name, 3), SUBSTRING(name, 2, 3), SUBSTR(name, 2), INSTR(name, 'x'), LOCATE('x', name) FROM t;
SELECT SUBSTRING(name FROM 2 FOR 3), SUBSTRING(name FROM 2) FROM t;
SELECT TRIM(LEADING ' ' FROM name), TRIM(TRAILING 'x' FROM name), TRIM(BOTH FROM name), TRIM('x' FROM name) FROM t;
SELECT POSITION('b' IN name) FROM t;
SELECT EXTRACT(YEAR FROM d), EXTRACT(MONTH FROM d), EXTRACT(EPOCH FROM ts), EXTRACT(DAY FROM INTERVAL '5' DAY) FROM t;
SELECT OVERLAY(name PLACING 'xx' FROM 2 FOR 3), OVERLAY(name PLACING 'yy' FROM 1) FROM t;
SELECT CHAR_LENGTH(name), CHARACTER_LENGTH(name USING CHARACTERS), OCTET_LENGTH(name), CHAR_LENGTH(name USING OCTETS) FROM t;
SELECT YEAR(d), MONTH(d), DAY(d), HOUR(ts), MINUTE(ts), SECOND(ts), DAYOFWEEK(d), WEEK(d), QUARTER(d) FROM t;
SELECT DATEADD(DAY, 1, d), DATEADD('MONTH', -1, d), DATEDIFF(DAY, d1, d2), DATE_TRUNC(MONTH, ts) FROM t;
SELECT FORMATDATETIME(ts, 'yyyy-MM-dd'), PARSEDATETIME('2024-01-01', 'yyyy-MM-dd'), TO_CHAR(ts, 'YYYY'), TO_DATE('2024', 'YYYY') FROM t;
SELECT CONVERT(x, INT), CONVERT(y, VARCHAR(20)), TRY_PARSE_INT(x) FROM t;
SELECT CONCAT(a, b, c), CONCAT_WS(',', a, b), REPEAT('-', 10), LPAD(x, 5, '0'), RPAD(x, 5), REGEXP_REPLACE(s, '[0-9]', '#'), REGEXP_LIKE(s, '^a', 'i'), REGEXP_SUBSTR(s, '\d+') FROM t;
SELECT JSON_OBJECT('id': id, 'name': name), JSON_OBJECT(KEY 'id' VALUE id), JSON_OBJECT('a' VALUE 1 NULL ON NULL), JSON_OBJECT() FROM t;
SELECT JSON_OBJECT('a': x ABSENT ON NULL WITH UNIQUE KEYS), JSON_OBJECT('v': JSON '[1]' FORMAT JSON) FROM t;
SELECT JSON_ARRAY(1, 2, 'three'), JSON_ARRAY(a, b NULL ON NULL), JSON_ARRAY(), JSON_ARRAY((SELECT id FROM t2)) FROM t;
SELECT JSON_ARRAY(x FORMAT JSON ABSENT ON NULL) FROM t;
SELECT CARDINALITY(arr), ARRAY_CONTAINS(arr, 1), ARRAY_CAT(arr, ARRAY[4]), ARRAY_APPEND(arr, 5), ARRAY_SLICE(arr, 1, 2), TRIM_ARRAY(arr, 1) FROM t;
SELECT HASH('SHA-256', name), ENCRYPT('AES', key, data), STRINGTOUTF8(s), UTF8TOSTRING(b), COMPRESS(b), ORA_HASH(name) FROM t;
SELECT DATABASE(), USER(), CURRENT_USER(), SCHEMA(), H2VERSION(), IDENTITY(), SCOPE_IDENTITY(), LAST_INSERT_ID(), LOCK_TIMEOUT(), MEMORY_FREE() FROM DUAL;
SELECT SET(@v, 5), ARRAY_GET(arr, 1), DISK_SPACE_USED('T'), FILE_READ('/tmp/x'), TRUNCATE_VALUE(s, 2, FALSE) FROM t;
SELECT ST_Area(geom), ST_Intersects(a, b), ST_MakePoint(1, 2), ST_X(p) FROM shapes;
SELECT PUBLIC.MY_FUNC(1, 2), my_schema.my_alias('x'), "MixedCase"(1) FROM DUAL;
SELECT IFNULL(NULL, 1), ZERO(), PI(), SIGN(-3), CEIL(1.2), FLOOR(1.8), LOG(10, 100), LN(2.7), EXP(1);
SELECT CSVWRITE('out.csv', 'SELECT * FROM t'), LINK_SCHEMA('X', '', 'jdbc:h2:mem:', 'sa', '', 'PUBLIC');
SELECT JSON_OBJECT('a':id, 'b': x), JSON_OBJECT('c':1) FROM t;
SELECT JSON_ARRAY(SELECT id FROM t ORDER BY id), JSON_ARRAY(SELECT name FROM t FORMAT JSON) FROM DUAL;
